  opacity: 0;
  pointer-events: none;
  transition: opacity 0.14s;
  position: absolute;
  left: 50%;
  top: auto;
  bottom: 120%;
  transform: translateX(-50%);
  background: #232933;
  color: #fff;
  font-size: 13px;
  border-radius: 7px;
  padding: 7px 12px;
  min-width: 190px;
  white-space: pre-line;
  box-shadow: 0 2px 14px rgba(0,0,0,0.20);
  text-align: left;
  z-index: 999;
}

.outstanding-tooltip-container:hover .outstanding-tooltip,
.outstanding-tooltip-container:focus-within .outstanding-tooltip {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}

@media (max-width: 700px) {
  /* On narrow screens, show beside instead of above */
  .outstanding-tooltip {
    left: 115%;
    bottom: auto;
    top: 0;
    transform: none;
    min-width: 140px;
    max-width: 60vw;
    white-space: normal;
  }
}
